-- Variantes de capas da DC Comics.
-- Execute depois de supabase/schema.sql no SQL Editor do Supabase.
-- Os inserts sao idempotentes e podem ser executados novamente.

-- Mantém compatibilidade com bancos que ainda tinham a validação exclusiva da DC.
alter table public.comic_cover_variants drop constraint if exists comic_cover_variants_cover_url_check;
alter table public.comic_cover_variants add constraint comic_cover_variants_cover_url_check check (
  cover_url ~ '^https://(www[.]|media[.]|i[.])?(static[.]dc[.]com|files[12][.]comics[.]org|storage[.]googleapis[.]com|dcuguide[.]com|static[.]wikia[.]nocookie[.]net|thepopverse[.]com|comicstoastonish[.]com|static[.]pulps[.]fr|sanctumsanctorumcomics[.]com|goldenapplecomics[.]com|blackdragoncomix[.]com|midtowncomics[.]com|everythingcomics[.]ca|thecomicmint[.]com|mlpnk72yciwc[.]i[.]optimole[.]com|media[.]forbiddenplanet[.]com|image[.]keycollectorcomics[.]com|comics[.]forbiddenplanet[.]co[.]uk|efantasy[.]gr|ebayimg[.]com|iwt[.]sfo2[.]cdn[.]digitaloceanspaces[.]com|shop[.]thirdeyecomics[.]com|dc[.]fandom[.]com|myshopville[.]com|cdn[.]shopify[.]com|supermanhomepage[.]com|sequentialartcomics[.]com|comickingdomcreative[.]com|img[.]hipcomic[.]com|media[.]mycomicshop[.]com|cardboardmemories[.]ca|oxfordcomicsandgames[.]com|alternateworldscomics[.]com|postimg[.]cc|imgur[.]com|ibb[.]co|comicvine[.]gamespot[.]com|zonafantasmanet[.]files[.]wordpress[.]com|stadiumcomics[.]com|cgc-emporium[.]com|marticomics[.]com|retconcomics[.]com|thecomicbookshoppe[.]com|comicsbox[.]it)/'
);
alter table public.user_cover_choices drop constraint if exists user_cover_choices_cover_url_check;
alter table public.user_cover_choices add constraint user_cover_choices_cover_url_check check (
  cover_url ~ '^https://(www[.]|media[.]|i[.])?(static[.]dc[.]com|files[12][.]comics[.]org|storage[.]googleapis[.]com|dcuguide[.]com|static[.]wikia[.]nocookie[.]net|thepopverse[.]com|comicstoastonish[.]com|static[.]pulps[.]fr|sanctumsanctorumcomics[.]com|goldenapplecomics[.]com|blackdragoncomix[.]com|midtowncomics[.]com|everythingcomics[.]ca|thecomicmint[.]com|mlpnk72yciwc[.]i[.]optimole[.]com|media[.]forbiddenplanet[.]com|image[.]keycollectorcomics[.]com|comics[.]forbiddenplanet[.]co[.]uk|efantasy[.]gr|ebayimg[.]com|iwt[.]sfo2[.]cdn[.]digitaloceanspaces[.]com|shop[.]thirdeyecomics[.]com|dc[.]fandom[.]com|myshopville[.]com|cdn[.]shopify[.]com|supermanhomepage[.]com|sequentialartcomics[.]com|comickingdomcreative[.]com|img[.]hipcomic[.]com|media[.]mycomicshop[.]com|cardboardmemories[.]ca|oxfordcomicsandgames[.]com|alternateworldscomics[.]com|postimg[.]cc|imgur[.]com|ibb[.]co|comicvine[.]gamespot[.]com|zonafantasmanet[.]files[.]wordpress[.]com|stadiumcomics[.]com|cgc-emporium[.]com|marticomics[.]com|retconcomics[.]com|thecomicbookshoppe[.]com|comicsbox[.]it)/'
);

-- Remove a capa de referência redundante que é igual à capa principal.
delete from public.comic_cover_variants
where item_id = 'shadow-war-2022-001'
  and variant_key = 'reference-cover';

-- Corrige os IDs antigos da Guerra pela Terra-3 para o formato usado pelo catálogo.
delete from public.comic_cover_variants
where (item_id = 'war-earth-3-2022-001' and variant_key in ('reference-cover', 'gleb-melnikov', 'liam-sharp', 'guillem-march'))
   or (item_id = 'war-earth-3-2022-002' and variant_key = 'gleb-melnikov');

-- Remove IDs antigos das séries recentes antes de inserir os IDs alinhados ao catálogo.
delete from public.comic_cover_variants
where item_id in (
  'dark-crisis-2022-001', 'dc-ko-2025-001', 'challengers-unknown-2025-001',
  'one-star-squadron-2022-001', 'shadow-war-2022-001', 'shadow-war-2022-002',
  'shadow-war-2022-003', 'shadow-war-2022-009', 'absolute-power-2024-001',
  'atom-project-2025-001', 'fire-ice-smallville-2023-001', 'flash-fastest-2022-001',
  'green-lantern-2021-001', 'green-lantern-2023-001', 'green-lantern-war-journal-2023-001',
  'justice-godzilla-kong-2023-001', 'justice-league-unlimited-2025-001', 'justice-society-2023-001',
  'knight-terrors-2023-001', 'lazarus-planet-2023-001', 'monkey-prince-2022-001',
  'new-gods-2025-001', 'next-batman-second-son-2021-001', 'nubia-amazons-2021-001',
  'penguin-2023-001', 'poison-ivy-2022-001', 'power-girl-special-2023-001',
  'question-watchtower-2024-001', 'robin-2021-001', 'shazam-2021-001', 'shazam-2023-001',
  'stargirl-lost-children-2022-001', 'superboy-tomorrow-2023-001', 'superman-2023-001',
  'superman-kal-el-returns-2022-001', 'superman-lost-2023-001', 'superman-son-kal-el-2021-001',
  'swamp-thing-2021-001', 'titans-2023-001', 'trial-amazons-2022-001', 'we-are-yesterday-2025-001',
  'wildcats-2023-001', 'wonder-girl-2021-001', 'wonder-woman-2023-001'
);

  -- Teen Titans Academy: as artes abaixo são hospedadas por lojas/serviços externos;
  -- a identificação das edições e dos artistas foi conferida no catálogo do GCD.
  ('teen-titans-academy-001', 'jamal-campbell', 'Jamal Campbell', 'https://dcuguide.com/images/d/d5/Teen_Titans_Academy_1_%28Cover_B%29.png', 'https://dcuguide.com/File:Teen_Titans_Academy_1_%28Cover_B%29.png'),
  ('teen-titans-academy-002', 'philip-tan', 'Philip Tan e Elmer Santos', 'https://goldenapplecomics.com/cdn/shop/products/0221DC077.jpg?v=1616857854', 'https://goldenapplecomics.com/products/176144'),
  ('teen-titans-academy-003', 'philip-tan', 'Philip Tan e Elmer Santos', 'https://static.pulps.fr/img/no-cat/full/0321DC094.jpg', 'https://www.comics.org/series/171160/covers/'),
  ('teen-titans-academy-004', 'stephen-byrne-pride', 'Stephen Byrne - DC Pride', 'https://sanctumsanctorumcomics.com/cdn/shop/products/182436-hr.jpg?v=1616636898&width=1946', 'https://www.dc.com/blog/2021/03/11/dc-announces-dc-pride-anthology-comic-to-arrive-june-8-and-more'),
  ('teen-titans-academy-005', 'philip-tan', 'Philip Tan e Elmer Santos', 'https://goldenapplecomics.com/cdn/shop/products/185505-hr.jpg?v=1619732894', 'https://goldenapplecomics.com/products/185505'),
  ('teen-titans-academy-anuario', 'rafa-sandoval', 'Rafa Sandoval, Jordi Tarragona e Alejandro Sánchez', 'https://blackdragoncomix.com/cdn/shop/products/TeenTitansAcademyYearbook2021_1CoverBVariantRafaSandovalCardStockCover_1200x1200.jpg?v=1624589460', 'https://www.comics.org/series/171160/covers/')
on conflict (item_id, variant_key) do update
set label = excluded.label,
    cover_url = excluded.cover_url,
    source_url = excluded.source_url;

